dot_atom <- function(tokens) {
  if (length(tokens) %% 2L == 0L) return(FALSE)
  for (i in seq_along(tokens)) if (tokens[[i]]$kind != if (i %% 2L == 1L) "word" else ".") return(FALSE)
  TRUE
}

address_peek <- function(parser) {
  if (parser$position <= length(parser$tokens)) parser$tokens[[parser$position]]$kind else ""
}
address_expect <- function(parser, kind) {
  if (address_peek(parser) != kind) parser$failed <- TRUE else parser$position <- parser$position + 1L
}
address_run <- function(parser, phrase) {
  start <- parser$position
  kinds <- c("word", ".", if (phrase) "quoted")
  while (address_peek(parser) %in% kinds) parser$position <- parser$position + 1L
  if (start == parser$position) list() else parser$tokens[seq.int(start, parser$position - 1L)]
}

display_name <- function(parser, phrase) {
  output <- character()
  previous <- FALSE
  for (i in seq_along(phrase)) {
    token <- phrase[[i]]
    text <- token$text
    decoded <- FALSE
    if (token$kind == "word") {
      value <- decode_word(text)
      text <- value$text
      decoded <- value$decoded
      parser$encoding_error <- parser$encoding_error || value$error
    }
    if (i > 1L && token$spaced && !(decoded && previous)) output <- c(output, " ")
    output <- c(output, text)
    previous <- decoded
  }
  collapse_whitespace(paste0(output, collapse = ""))
}

address_mailbox <- function(parser, phrase, local, domain, named) {
  if (!dot_atom(local) || !dot_atom(domain)) {
    parser$failed <- TRUE
    return(NULL)
  }
  token_text <- function(tokens) paste0(vapply(tokens, function(token) token$text, character(1)), collapse = "")
  list(kind = "mailbox", name = if (named) display_name(parser, phrase) else "",
       address = ascii_lower(paste0(token_text(local), "@", token_text(domain))))
}

parse_address <- function(parser, in_group) {
  phrase <- address_run(parser, TRUE)
  following <- address_peek(parser)
  if (following == "<") {
    parser$position <- parser$position + 1L
    local <- address_run(parser, FALSE)
    address_expect(parser, "@")
    domain <- address_run(parser, FALSE)
    address_expect(parser, ">")
    return(address_mailbox(parser, phrase, local, domain, TRUE))
  }
  if (following == "@") {
    parser$position <- parser$position + 1L
    domain <- address_run(parser, FALSE)
    return(address_mailbox(parser, list(), phrase, domain, FALSE))
  }
  if (following == ":" && length(phrase) > 0L && !in_group) {
    parser$position <- parser$position + 1L
    mailboxes <- list()
    if (address_peek(parser) != ";") {
      repeat {
        entry <- parse_address(parser, TRUE)
        if (parser$failed || is.null(entry) || entry$kind != "mailbox") {
          parser$failed <- TRUE
          return(NULL)
        }
        mailboxes[[length(mailboxes) + 1L]] <- entry
        if (address_peek(parser) != ",") break
        parser$position <- parser$position + 1L
      }
    }
    address_expect(parser, ";")
    return(list(kind = "group", mailboxes = mailboxes))
  }
  parser$failed <- TRUE
  NULL
}

parse_address_list <- function(value) {
  tokens <- tokenize(value)
  if (is.null(tokens) || length(tokens) == 0L) return(NULL)
  parser <- new.env(parent = emptyenv())
  parser$tokens <- tokens
  parser$position <- 1L
  parser$encoding_error <- parser$failed <- FALSE
  addresses <- list()
  repeat {
    address <- parse_address(parser, FALSE)
    if (parser$failed || is.null(address)) return(NULL)
    addresses[[length(addresses) + 1L]] <- address
    if (address_peek(parser) != ",") break
    parser$position <- parser$position + 1L
  }
  if (parser$position <= length(tokens)) return(NULL)
  list(addresses = addresses, error = parser$encoding_error)
}

weekdays <- c("mon", "tue", "wed", "thu", "fri", "sat", "sun")
months <- c("jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")
named_zones <- c(ut = 0, gmt = 0, z = 0, est = -300, edt = -240, cst = -360, cdt = -300,
                 mst = -420, mdt = -360, pst = -480, pdt = -420)
leap <- function(year) year %% 4 == 0 && year %% 100 != 0 || year %% 400 == 0
year_days <- function(year) if (leap(year)) 366 else 365
month_days <- function(year, month) {
  if (month == 2L && leap(year)) return(29)
  c(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)[month]
}
has_digits <- function(text, lengths) nchar(text) %in% lengths && grepl("^[0-9]+$", text)

parse_date <- function(value) {
  failure <- function(error) list(date = NULL, error = error)
  text <- remove_comments(value)
  if (is.null(text)) return(failure("bad Date syntax"))
  tokens <- split_words(gsub(",", " , ", text, fixed = TRUE))
  weekday <- NA_integer_
  if (length(tokens) >= 3L && tokens[2L] == ",") {
    weekday <- match(ascii_lower(tokens[1L]), weekdays) - 1L
    if (!is.na(weekday)) tokens <- tokens[-c(1L, 2L)]
  }
  if (length(tokens) != 5L) return(failure("bad Date syntax"))
  pieces <- strsplit(paste0(tokens[4L], ":X"), ":", fixed = TRUE)[[1L]]
  pieces <- pieces[-length(pieces)]
  month <- match(ascii_lower(tokens[2L]), months)
  zone <- tokens[5L]
  numeric_zone <- nchar(zone) == 5L && substr(zone, 1L, 1L) %in% c("+", "-") && has_digits(substring(zone, 2L), 4L)
  offset <- unname(named_zones[ascii_lower(zone)])
  if (!has_digits(tokens[1L], c(1L, 2L)) || is.na(month) || !has_digits(tokens[3L], c(2L, 4L)) ||
      !(length(pieces) %in% c(2L, 3L)) || any(!vapply(pieces, has_digits, logical(1), lengths = 2L)) ||
      !(numeric_zone || !is.na(offset))) return(failure("bad Date syntax"))
  day <- as.numeric(tokens[1L])
  year <- as.numeric(tokens[3L])
  if (nchar(tokens[3L]) == 2L) year <- year + if (year < 50) 2000 else 1900
  hour <- as.numeric(pieces[1L])
  minute <- as.numeric(pieces[2L])
  second <- if (length(pieces) == 3L) as.numeric(pieces[3L]) else 0
  if (numeric_zone) {
    hh <- as.numeric(substr(zone, 2L, 3L))
    mm <- as.numeric(substr(zone, 4L, 5L))
    if (hh > 23 || mm > 59) return(failure("Date out of range"))
    offset <- (hh * 60 + mm) * if (startsWith(zone, "-")) -1 else 1
  }
  if (year < 1970 || year > 2099 || day < 1 || day > month_days(year, month) ||
      hour > 23 || minute > 59 || second > 59) return(failure("Date out of range"))
  days <- 0
  if (year > 1970) for (current in seq.int(1970, year - 1)) days <- days + year_days(current)
  if (month > 1L) for (current in seq_len(month - 1L)) days <- days + month_days(year, current)
  days <- days + day - 1
  seconds <- days * 86400 + hour * 3600 + minute * 60 + second - offset * 60
  if (seconds < 0) return(failure("Date out of range"))
  if (!is.na(weekday) && (days + 3) %% 7 != weekday) return(failure("Date weekday mismatch"))
  list(date = seconds, error = "")
}

format_utc <- function(seconds) {
  days <- seconds %/% 86400
  rest <- seconds %% 86400
  year <- 1970
  while (days >= year_days(year)) {
    days <- days - year_days(year)
    year <- year + 1
  }
  month <- 1L
  while (days >= month_days(year, month)) {
    days <- days - month_days(year, month)
    month <- month + 1L
  }
  sprintf("%04d-%02d-%02d %02d:%02d:%02d", as.integer(year), month, as.integer(days + 1),
          as.integer(rest %/% 3600), as.integer((rest %% 3600) %/% 60), as.integer(rest %% 60))
}

ascii_lower <- function(text) chartr("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz", text)
chars <- function(text) strsplit(text, "", fixed = TRUE)[[1L]]
split_lf <- function(text) {
  pieces <- strsplit(paste0(text, "\nX"), "\n", fixed = TRUE)[[1L]]
  pieces[-length(pieces)]
}
split_words <- function(text) {
  words <- strsplit(text, "[ \t]+")[[1L]]
  words[nzchar(words)]
}
collapse_whitespace <- function(text) paste(split_words(text), collapse = " ")
strip_whitespace <- function(text) sub("[ \t]+$", "", sub("^[ \t]+", "", text))
strip_trailing <- function(text) sub("[ \t]+$", "", text)

header_value <- function(header, name) {
  name <- ascii_lower(name)
  for (field in header$fields) if (field$name == name) return(field$value)
  NULL
}
header_count <- function(header, name) sum(vapply(header$fields, function(field) field$name == ascii_lower(name), logical(1)))

parse_fields <- function(lines) {
  fields <- list()
  invalid <- integer()
  in_field <- FALSE
  for (line in lines) {
    text <- line$text
    if (nchar(text) > 0L && substr(text, 1L, 1L) %in% c(" ", "\t")) {
      if (in_field) {
        last <- length(fields)
        fields[[last]]$value <- paste0(fields[[last]]$value, text)
      } else invalid <- c(invalid, line$number)
      next
    }
    colon <- regexpr(":", text, fixed = TRUE)[1L]
    name <- if (colon > 0L) substr(text, 1L, colon - 1L) else ""
    codes <- utf8ToInt(name)
    in_field <- colon > 1L && all(codes >= 33L & codes <= 126L)
    if (in_field) {
      fields[[length(fields) + 1L]] <- list(name = ascii_lower(name), value = substring(text, colon + 1L))
    } else invalid <- c(invalid, line$number)
  }
  for (i in seq_along(fields)) fields[[i]]$value <- strip_whitespace(fields[[i]]$value)
  list(fields = fields, invalid = invalid)
}

remove_comments <- function(text) {
  output <- character()
  depth <- 0L
  position <- 1L
  while (position <= nchar(text)) {
    char <- substr(text, position, position)
    if (depth == 0L) {
      if (char == "(") {
        depth <- 1L
        output <- c(output, " ")
      } else output <- c(output, char)
    } else if (char == "\\") {
      position <- position + 1L
    } else if (char == "(") {
      depth <- depth + 1L
    } else if (char == ")") depth <- depth - 1L
    position <- position + 1L
  }
  if (depth != 0L) return(NULL)
  paste0(output, collapse = "")
}

tokenize <- function(text, mime = FALSE) {
  specials <- chars(if (mime) "/;=" else "<>:;@,.")
  address_words <- chars("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-/=?^_`{|}~")
  excluded <- chars("()<>@,;:\\\"/[]?=")
  is_word <- function(char) {
    if (!mime) return(char %in% address_words)
    code <- utf8ToInt(char)
    code >= 33L && code <= 126L && !(char %in% excluded)
  }
  tokens <- list()
  position <- 1L
  spaced <- FALSE
  while (position <= nchar(text)) {
    char <- substr(text, position, position)
    if (char %in% c(" ", "\t")) {
      spaced <- TRUE
      position <- position + 1L
      next
    }
    if (char == "(") {
      depth <- 1L
      position <- position + 1L
      while (position <= nchar(text) && depth > 0L) {
        char <- substr(text, position, position)
        if (char == "\\") {
          position <- position + 2L
          next
        }
        if (char == "(") depth <- depth + 1L
        if (char == ")") depth <- depth - 1L
        position <- position + 1L
      }
      if (depth != 0L) return(NULL)
      spaced <- TRUE
      next
    }
    if (char == '"') {
      value <- character()
      position <- position + 1L
      closed <- FALSE
      while (position <= nchar(text)) {
        char <- substr(text, position, position)
        position <- position + 1L
        if (char == '"') {
          closed <- TRUE
          break
        }
        if (char == "\\") {
          if (position > nchar(text)) return(NULL)
          char <- substr(text, position, position)
          position <- position + 1L
        }
        value <- c(value, char)
      }
      if (!closed) return(NULL)
      token <- list(kind = "quoted", text = paste0(value, collapse = ""), spaced = spaced)
    } else if (char %in% specials) {
      token <- list(kind = char, text = char, spaced = spaced)
      position <- position + 1L
    } else if (is_word(char)) {
      end <- position + 1L
      while (end <= nchar(text) && is_word(substr(text, end, end))) end <- end + 1L
      token <- list(kind = "word", text = substr(text, position, end - 1L), spaced = spaced)
      position <- end
    } else return(NULL)
    tokens[[length(tokens) + 1L]] <- token
    spaced <- FALSE
  }
  tokens
}

decode_word <- function(word) {
  unchanged <- function(error = FALSE) list(text = word, decoded = FALSE, error = error)
  if (nchar(word) < 4L || !startsWith(word, "=?") || !endsWith(word, "?=")) return(unchanged())
  inside <- substr(word, 3L, nchar(word) - 2L)
  pieces <- strsplit(paste0(inside, "?X"), "?", fixed = TRUE)[[1L]]
  pieces <- pieces[-length(pieces)]
  if (length(pieces) != 3L || any(!nzchar(pieces))) return(unchanged())
  if (ascii_lower(pieces[1L]) != "us-ascii") return(unchanged(TRUE))
  data <- NULL
  if (pieces[2L] %in% c("B", "b")) {
    data <- strict_base64(pieces[3L])
  } else if (pieces[2L] %in% c("Q", "q")) {
    data <- integer()
    position <- 1L
    while (position <= nchar(pieces[3L])) {
      char <- substr(pieces[3L], position, position)
      if (char == "_") {
        data <- c(data, 32L)
        position <- position + 1L
      } else if (char == "=") {
        value <- escaped_byte(pieces[3L], position)
        if (is.null(value)) return(unchanged(TRUE))
        data <- c(data, value)
        position <- position + 3L
      } else {
        data <- c(data, utf8ToInt(char))
        position <- position + 1L
      }
    }
  }
  if (is.null(data) || any(data < 32L | data > 126L)) return(unchanged(TRUE))
  list(text = intToUtf8(data), decoded = TRUE, error = FALSE)
}

decode_unstructured <- function(value) {
  output <- character()
  previous <- FALSE
  error <- FALSE
  words <- split_words(value)
  for (i in seq_along(words)) {
    decoded <- decode_word(words[i])
    if (i > 1L && !(decoded$decoded && previous)) output <- c(output, " ")
    output <- c(output, decoded$text)
    previous <- decoded$decoded
    error <- error || decoded$error
  }
  list(text = collapse_whitespace(paste0(output, collapse = "")), error = error)
}

parse_parameters <- function(value, with_subtype) {
  tokens <- tokenize(value, TRUE)
  if (is.null(tokens) || length(tokens) == 0L || tokens[[1L]]$kind != "word") return(NULL)
  main_type <- ascii_lower(tokens[[1L]]$text)
  subtype <- ""
  position <- 2L
  if (with_subtype) {
    if (length(tokens) < 3L || tokens[[2L]]$kind != "/" || tokens[[3L]]$kind != "word") return(NULL)
    subtype <- ascii_lower(tokens[[3L]]$text)
    position <- 4L
  }
  parameters <- list()
  while (position <= length(tokens)) {
    if (position + 3L > length(tokens) || tokens[[position]]$kind != ";" ||
        tokens[[position + 1L]]$kind != "word" || tokens[[position + 2L]]$kind != "=" ||
        !(tokens[[position + 3L]]$kind %in% c("word", "quoted"))) return(NULL)
    name <- ascii_lower(tokens[[position + 1L]]$text)
    if (is.null(parameters[[name]])) parameters[[name]] <- tokens[[position + 3L]]$text
    position <- position + 4L
  }
  list(main_type = main_type, subtype = subtype, parameters = parameters)
}

